func (r *mutationResolver) CreateOrder(ctx context.Context, input model.CreateOrderInput, idempotencyKey string) (*model.Order, error) {
	newOrder, err := r.OrderService.CreateWithIdempotencyKey(ctx, input, idempotencyKey)

	if err != nil {
		return nil, err
	}

	// 2. --- MAGIA DE WEBSOCKETS ---
	// Avisar a todos los que escuchan ese restaurante
	r.mu.Lock()
	observers := r.OrderObservers[input.Restaurant]
	for _, observer := range observers {
		observer <- newOrder // Enviar la orden al canal
	}
	r.mu.Unlock()

	return newOrder, nil
}

// UpdateOrderStatus is the resolver for the updateOrderStatus field.
func (r *mutationResolver) UpdateOrderStatus(ctx context.Context, id string, status string) (*model.Order, error) {
	updatedOrder, err := r.OrderService.UpdateStatus(ctx, id, status)
	if err != nil {
		return nil, err
	}

	// Avisar a los observadores del cambio de estado
	order, err := r.OrderService.FindOne(ctx, id)
	if err == nil {
		r.mu.Lock()
		observers := r.OrderObservers[order.RestaurantID]
		for _, observer := range observers {
			observer <- updatedOrder
		}
		r.mu.Unlock()
	}

	return updatedOrder, nil
}

