// OrderCreated is the resolver for the orderCreated field.
func (r *subscriptionResolver) OrderCreated(ctx context.Context, restaurantID int) (<-chan *model.Order, error) {
	// 1. Crear un canal para este cliente específico
	// El buffer de 1 evita bloqueos si el cliente es lento
	ch := make(chan *model.Order, 1)

	// 2. Guardar el canal en la lista de observadores de ese restaurante
	r.mu.Lock()
	r.OrderObservers[restaurantID] = append(r.OrderObservers[restaurantID], ch)
	r.mu.Unlock()

	// 3. Manejar la desconexión (Cuando el cocinero cierra la pestaña)
	go func() {
		<-ctx.Done() // Esperar a que el cliente se vaya
		r.mu.Lock()
		observers := r.OrderObservers[restaurantID]
		for i, observer := range observers {
			if observer == ch {
				r.OrderObservers[restaurantID] = append(observers[:i], observers[i+1:]...)
				break
			}
		}
		close(ch)
		r.mu.Unlock()
	}()

	// 4. Devolver el canal a gqlgen para que lo convierta en WebSocket
	return ch, nil
}

// OrderStatusUpdated is the resolver for the orderStatusUpdated field.
